// Define our namespace.
namespace Ninlil.Dns.Data.Abstractions.Entity;

/// <summary>
///     This class is the base that every persisted Ninlil entity builds on. It carries only
///     the two things every stored record needs regardless of what it represents or which
///     database engine holds it: a unique identifier, and the moment it was first written.
/// </summary>
public abstract class EntityBase
{
    /// <summary>
    ///     This property contains the entity's unique identifier. It is generated by the caller
    ///     that creates the entity (rather than by the database), so that the same identifier is
    ///     usable whether the record ends up in a relational database or in MongoDB.
    /// </summary>
    public Guid Id { get; set; }

    /// <summary>
    ///     This property contains the UTC date and time at which the entity was first written to
    ///     storage.
    /// </summary>
    public DateTimeOffset CreatedAtUtc { get; set; }
}
